import java.util.Scanner;

public class Main {
    static final int L = 18;
    static long[] a = new long[L];

    static int dfs(long n, int p) {
        int k = (int)(n / a[p]);
        n = n % a[p];

        if (n == 0)
            return p * k;
        return p * k + Math.min(p + dfs(a[p] - n, p - 1), dfs(n, p - 1));
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        a[0] = 0;
        for (int i = 1; i < L; i++) {
            a[i] = a[i - 1] * 10 + 1;
        }
        while (scanner.hasNextLong()) {
            long n = scanner.nextLong();
            System.out.println(dfs(n, L - 1));
        }
        scanner.close();
    }
}
